\title{The Half-Plane Cut on the Modular Circle:\\
A Separable Bulk, a Local Parity, and a Square-Root Fluctuation}
\author{Aristotle}
\date{13 August 2026}

\begin{document}
\maketitle

\begin{abstract}
For a modulus $N$ let $\Circ(N)=\{(x,y)\in[0,N)^2 : x^2+y^2\equiv 1 \pmod N\}$ be the
modular circle and $C(N)=|\Circ(N)|$ its cardinality. The count $C$ is \emph{separable}:
it is multiplicative over coprime factorisations, and for odd $N$ it admits the closed form
$C(N)=\prod_{p\mid N}p^{\,v_p(N)-1}\bigl(p-\chi_p(-1)\bigr)$, where $\chi_p(-1)=+1$ if
$p\equiv 1 \pmod 4$ and $-1$ otherwise. We study the \emph{half-plane count}
$H(N)=\#\{(x,y)\in\Circ(N) : 2(x+y)<N\}$, obtained by conditioning the circle on an
order-theoretic --- hence non-congruential, hence non-separable --- cut. We prove that $H$
lies outside the separable class ($H(35)=6\neq 4=H(5)H(7)$), and then show that this escape
is structurally sealed in three independent ways: an exact reflection identity
$H(N)=\high(N)+2R(N)$ with $2R(N)=S(N)$ separable, so that all non-separability is carried
by the corner count $\high$; a sharp quadrant bound $4\,\high(N)\le C(N)$; and a parity
theorem $H(N)\equiv D(N)\pmod 2$, where $D(N)$ counts $x$ with $2x^2\equiv 1$ and $4x<N$.
Full enumeration for $15\le N\le 62\,879$ shows that the deviation
$\varepsilon(N)=H(N)-C(N)/8$ is genuinely factor-dependent but of size $O(\sqrt N)$ and
uncorrelated with the trace coordinates of the factorisation. We conclude that crossing the
separability boundary produces factor-dependence only at the square-root noise floor, a seal
due to aggregation rather than to separability. As an application on the separable side, for
Blum-type semiprimes $N=pq$ with $p\equiv q\equiv 3 \pmod 4$ we prove $C(N)=N+p+q+1$, so
$C(N)$ determines the factorisation via Vieta's formulas --- with the sole obstruction that
evaluating $C(N)$ without the factorisation costs $\Theta(N)$ operations.
\end{abstract}

\section{Introduction}

\subsection{Separable statistics and the classification boundary}

Let $N\ge 1$ and consider the affine conic $x^2+y^2=1$ over $\mathbb{Z}/N\mathbb{Z}$. Its
point count is easy for one structural reason: the defining condition is a
\emph{congruence}, and congruences respect the Chinese Remainder decomposition
\[
  \mathbb{Z}/mn\mathbb{Z}\;\cong\;\mathbb{Z}/m\mathbb{Z}\times\mathbb{Z}/n\mathbb{Z},
  \qquad \gcd(m,n)=1 .
\]
Any set defined by congruences alone therefore has cardinality equal to a product of local
cardinalities. We call such a count \emph{CRT-separable}, or simply \emph{separable}.

Separable statistics have a double character: they are completely classified, and they carry
no \emph{usable} factorisation information, because computing them requires either the
factorisation itself or an exhaustive enumeration. This motivates the question of this paper.

\begin{quote}
\textbf{Question.} If we condition a modular counting problem on a constraint not expressible
by congruences --- so that the resulting count provably falls outside the separable
classification --- does the count acquire accessible information about the factorisation
of~$N$?
\end{quote}

The cleanest non-congruential constraint is an \emph{order} constraint on canonical
representatives. Fixing $x,y\in\{0,1,\dots,N-1\}$ and imposing $x+y<N/2$, with the sum taken
in $\mathbb{Z}$ and not in $\mathbb{Z}/N\mathbb{Z}$, destroys separability directly: the CRT
isomorphism is a ring isomorphism and does not respect the ordering of representatives.

\subsection{Summary of results}

On the separable side we obtain a complete closed form (Theorems~\ref{thm:crt},
\ref{thm:prime}, \ref{thm:ppow}, \ref{thm:closed}) together with a $2$-adic divisibility
(Proposition~\ref{prop:twoadic}) and the Blum-semiprime recovery
(Theorems~\ref{thm:blum}--\ref{thm:vieta}). On the non-separable side we prove failure of
multiplicativity (Theorem~\ref{thm:nonsep}), the reflection identity (Theorem~\ref{thm:refl}),
the halving $2R=S$ (Theorem~\ref{thm:half}), the quadrant bound (Theorem~\ref{thm:quad}) and
the parity theorem (Theorem~\ref{thm:parity}). Section~\ref{sec:quant} reports the
quantitative behaviour of $\varepsilon(N)=H(N)-C(N)/8$.

\section{Definitions}

Throughout, representatives are taken in $[0,N)\cap\mathbb{Z}$.

\begin{definition}[Modular circle]
$\Circ(N)=\{(x,y)\in[0,N)^2 : x^2+y^2\equiv 1\ (\mathrm{mod}\ N)\}$ and $C(N)=|\Circ(N)|$.
\end{definition}

\begin{definition}[Half-plane and corner counts]
$H(N)=\#\{(x,y)\in\Circ(N) : 2(x+y)<N\}$ and $\high(N)=\#\{(x,y)\in\Circ(N):3N<2(x+y)\}$.
\end{definition}

\begin{definition}[Square roots of unity]
$S(N)=\#\{u\in[0,N):u^2\equiv 1\}$ and $R(N)=\#\{u\in[0,N):u^2\equiv 1,\ 2u<N\}$.
\end{definition}

\begin{definition}[Diagonal count]
$D(N)=\#\{x\in[0,N) : 2x^2\equiv 1\ (\mathrm{mod}\ N),\ 4x<N\}$.
\end{definition}

\begin{definition}[Local character]
For an odd prime $p$, $\chi_p$ is the quadratic character of $\mathbb{F}_p$; thus
$\chi_p(-1)=+1$ if $p\equiv 1\pmod 4$ and $\chi_p(-1)=-1$ if $p\equiv 3\pmod 4$.
\end{definition}

