\section{The separable baseline}

\begin{theorem}[Separability of the circle count]\label{thm:crt}
If $\gcd(m,n)=1$ then $C(mn)=C(m)C(n)$.
\end{theorem}

\begin{proof}[Proof sketch]
The Chinese Remainder map $e:\mathbb{Z}/mn\mathbb{Z}\to\mathbb{Z}/m\mathbb{Z}\times
\mathbb{Z}/n\mathbb{Z}$ is a ring isomorphism, so
$(x,y)\mapsto\bigl((e(x)_1,e(y)_1),(e(x)_2,e(y)_2)\bigr)$ carries a solution of $x^2+y^2=1$
modulo $mn$ to a pair of solutions modulo $m$ and modulo $n$. Injectivity follows from
injectivity of $e$ in each coordinate and surjectivity from applying $e^{-1}$ componentwise.
\end{proof}

\begin{definition}
For an odd prime $p$ the \emph{admissible slope set} is $T_p=\{t\in\mathbb{F}_p:1+t^2\neq 0\}$.
\end{definition}

\begin{theorem}[Prime conic count]\label{thm:prime}
For every odd prime $p$,
\[
  C(p)=p-\chi_p(-1)=
  \begin{cases} p-1, & p\equiv 1 \pmod 4,\\ p+1, & p\equiv 3 \pmod 4.\end{cases}
\]
\end{theorem}

\begin{proof}[Proof sketch]
Project stereographically from $(-1,0)\in\Circ(p)$. If $(x,y)$ is on the circle and
$(x,y)\neq(-1,0)$ then $1+x\neq 0$: indeed $x=-1$ forces $y^2=0$, hence $y=0$, the excluded
point. Setting $t=y/(1+x)$ one computes on the conic
\[
  1+t^2=\frac{(1+x)^2+(1-x^2)}{(1+x)^2}=\frac{2}{1+x}\neq 0 ,
\]
since $p$ is odd. The inverse is the classical rational parametrisation
$t\mapsto\bigl((1-t^2)/(1+t^2),\,2t/(1+t^2)\bigr)$, defined exactly on $T_p$, landing on the
circle and never at $(-1,0)$ (which would force $2=0$); the two maps are mutually inverse by
the same identity $1+t^2=2/(1+x)$. Hence $C(p)=|T_p|+1$. Finally, the complement of $T_p$ is
$\{t:t^2=-1\}$, of cardinality $\chi_p(-1)+1$, so $|T_p|=p-\chi_p(-1)-1$. The case split is
the first supplement to quadratic reciprocity, $\chi_p(-1)=(-1)^{(p-1)/2}$.
\end{proof}

\begin{lemma}[Linear congruence count]\label{lem:lin}
Let $p$ be prime and $\alpha,\beta,\gamma\in\mathbb{F}_p$ with $(\alpha,\beta)\neq(0,0)$. Then
$\#\{(s,t)\in\mathbb{F}_p^2:\alpha s+\beta t=\gamma\}=p$.
\end{lemma}

\begin{proof}[Proof sketch]
If $\alpha\neq0$ the projection $(s,t)\mapsto t$ is a bijection onto $\mathbb{F}_p$, with
inverse $t\mapsto\bigl((\gamma-\beta t)/\alpha,t\bigr)$; symmetrically if $\beta\neq0$.
\end{proof}

\begin{lemma}[Fibre count]\label{lem:fibre}
Let $p$ be an odd prime, $M\ge 2$ with $p\mid M$, and $(a,b)\in\Circ(M)$. Then exactly $p$
points of $\Circ(pM)$ reduce to $(a,b)$ modulo $M$.
\end{lemma}

\begin{proof}[Proof sketch]
Write $a^2+b^2=Mc+1$. A lift is $(a+sM,\,b+tM)$ with $0\le s,t<p$, and
\[
  (a+sM)^2+(b+tM)^2-1 \;=\; M\bigl(c+2(as+bt)\bigr)+M^2(s^2+t^2),
\]
so, since $p\mid M$, the lift lies on $\Circ(pM)$ if and only if
$c+2(as+bt)\equiv 0 \pmod p$. As $p\mid M$ and $a^2+b^2\equiv 1 \pmod p$, the pair $(a,b)$ is
not $\equiv(0,0)$ modulo $p$, and $2\neq 0$ in $\mathbb{F}_p$; apply Lemma~\ref{lem:lin}.
\end{proof}

\begin{theorem}[Prime powers]\label{thm:ppow}
For an odd prime $p$ and $k\ge 1$, $C(p^k)=p^{k-1}C(p)=p^{k-1}\bigl(p-\chi_p(-1)\bigr)$.
\end{theorem}

\begin{proof}[Proof sketch]
Summing Lemma~\ref{lem:fibre} over the fibres of reduction gives $C(pM)=p\,C(M)$ whenever
$p\mid M$, $M\ge 2$; induct on $k$.
\end{proof}

\begin{theorem}[Closed form for odd moduli]\label{thm:closed}
For every odd $N\ge 1$,
\[
  C(N)\;=\;\prod_{p\mid N}p^{\,v_p(N)-1}\bigl(p-\chi_p(-1)\bigr)
        \;=\;N\prod_{p\mid N}\Bigl(1-\frac{\chi_p(-1)}{p}\Bigr).
\]
In particular $C(N)=\prod_{p\mid N}(p-\chi_p(-1))$ for odd squarefree $N$.
\end{theorem}

\begin{proof}[Proof sketch]
Combine Theorem~\ref{thm:crt} with Theorem~\ref{thm:ppow}.
\end{proof}

\begin{proposition}[A $2$-adic constraint]\label{prop:twoadic}
For odd squarefree $N$ with $\omega(N)$ distinct prime factors, $4^{\omega(N)}\mid C(N)$.
\end{proposition}

\begin{proof}[Proof sketch]
Each local factor is $p-1$ with $p\equiv1\pmod4$ or $p+1$ with $p\equiv3\pmod4$; both are
divisible by $4$.
\end{proof}

For instance $C(15)=4\cdot4=16$, $C(35)=4\cdot8=32$, $C(105)=4\cdot4\cdot8=128$,
$C(9)=3\cdot4=12$, $C(25)=5\cdot4=20$, $C(225)=(3\cdot4)(5\cdot4)=240$.

\section{The half-plane cut and its symmetries}

\begin{lemma}[Sign flips]\label{lem:flip}
For $a\le N$ one has $(N-a)^2\equiv a^2 \pmod N$. Hence the reflections $x\mapsto N-x$ and
$y\mapsto N-y$ preserve the circle whenever the coordinates stay in range.
\end{lemma}

Write $\Low(N)$ for the low points ($2(x+y)<N$), $\High(N)$ for the corner ($3N<2(x+y)$), and
split $\Low(N)$ into its \emph{inner} part (both coordinates $\ge 1$) and its \emph{axis} part.

\begin{lemma}[Corner coordinates]\label{lem:corner}
If $(x,y)\in\High(N)$ then $2x>N$ and $2y>N$.
\end{lemma}

\begin{proof}[Proof sketch]
Both $x,y<N$, so $2(x+y)>3N$ gives $2x>3N-2y>N$, and symmetrically.
\end{proof}

\begin{lemma}[Antipodal bijection]\label{lem:anti}
The map $(x,y)\mapsto(N-x,N-y)$ is a bijection from the inner low points onto $\High(N)$.
\end{lemma}

\begin{proof}[Proof sketch]
If $(x,y)$ is low and inner then $N-x,N-y\in[1,N)$ and $2\bigl((N-x)+(N-y)\bigr)=4N-2(x+y)>3N$;
membership on the circle is Lemma~\ref{lem:flip}. Conversely a corner point has both
coordinates $>N/2\ge 1$ by Lemma~\ref{lem:corner}, so its reflection is inner and low. The map
is an involution.
\end{proof}

\begin{theorem}[Reflection identity]\label{thm:refl}
For $N\ge 2$, \; $H(N)=\high(N)+2R(N)$.
\end{theorem}

\begin{proof}[Proof sketch]
Partition $\Low(N)$ into inner and axis parts. The inner part has cardinality $\high(N)$ by
Lemma~\ref{lem:anti}. The axis part consists of the points $(0,u)$ and $(u,0)$ with
$u^2\equiv 1$ and $2u<N$; the two families are disjoint (a common element forces $u=0$, and
$0^2\not\equiv1$ for $N\ge2$) and each is in bijection with the small unit roots.
\end{proof}

\begin{theorem}[Halving of the unit roots]\label{thm:half}
For $N\ge 3$, \; $2R(N)=S(N)$.
\end{theorem}

\begin{proof}[Proof sketch]
The involution $u\mapsto N-u$ preserves the set of square roots of unity and exchanges
$\{2u<N\}$ with $\{2u>N\}$. It has no fixed point: if $2u=N$ and $u^2=Nk+1$ then $u\mid Nk$
and $u\mid u^2$, so $u\mid 1$, forcing $u=1$, $N=2$, excluded. Also $u=0$ is never a root.
\end{proof}

\begin{proposition}\label{prop:Ssep}
$S(mn)=S(m)S(n)$ for $\gcd(m,n)=1$, and $S(N)=2^{\omega(N)}$ for odd $N$.
\end{proposition}

Theorems~\ref{thm:refl} and~\ref{thm:half} combine to $H(N)=\high(N)+S(N)$ with $S$
separable: \emph{all} the non-separability of $H$ is concentrated in the corner count.

\begin{theorem}[Quadrant bound]\label{thm:quad}
For $N\ge 1$, \; $4\,\high(N)\le C(N)$. The constant $4$ is optimal:
$8\,\high(9)=16>12=C(9)$.
\end{theorem}

\begin{proof}[Proof sketch]
Consider the four images of $\High(N)$ under the group generated by $x\mapsto N-x$ and
$y\mapsto N-y$; all lie in $\Circ(N)$ by Lemma~\ref{lem:flip}. By Lemma~\ref{lem:corner} each
image is characterised by the sign pattern of $(2x-N,\,2y-N)$: $(+,+)$, $(-,-)$, $(-,+)$,
$(+,-)$ respectively, so the four are pairwise disjoint; and each reflection is injective on
the corner. The union thus has $4\,\high(N)$ elements inside $\Circ(N)$.
\end{proof}

\begin{corollary}[Sandwich between separable quantities]\label{cor:sandwich}
For $N\ge 3$, \; $2\le H(N)$ and $4H(N)\le C(N)+4S(N)$.
\end{corollary}

\begin{proof}[Proof sketch]
$u=1$ is always a small unit root, so $H\ge 2R\ge 2$. Multiply the reflection identity by $4$
and apply Theorem~\ref{thm:quad} together with $2R=S$.
\end{proof}

\section{Parity is diagonal-local; non-separability is real}

The half-plane condition depends only on $x+y$, hence is invariant under the swap
$\sigma(x,y)=(y,x)$, which also preserves the circle. Its fixed points on $\Low(N)$ are the
diagonal points, where the circle equation becomes $2x^2\equiv 1$ and the cut becomes $4x<N$.

\begin{lemma}\label{lem:diag}
The diagonal part of $\Low(N)$ is in bijection with
$\{x\in[0,N):2x^2\equiv1\ (\mathrm{mod}\ N),\ 4x<N\}$, hence has cardinality $D(N)$; and
$\sigma$ restricts to a fixed-point-free involution of the off-diagonal part, exchanging
$\{x<y\}$ with $\{x>y\}$.
\end{lemma}

\begin{theorem}[Parity of the half-plane count]\label{thm:parity}
For all $N\ge 1$, \; $H(N)\equiv D(N) \pmod 2$. Consequently
$\high(N)\equiv D(N)\pmod 2$ for $N\ge 2$.
\end{theorem}

\begin{proof}[Proof sketch]
Partition $\Low(N)$ into diagonal and off-diagonal parts and apply Lemma~\ref{lem:diag}; the
consequence follows from Theorem~\ref{thm:refl} since $2R(N)$ is even.
\end{proof}

The moduli $N<80$ with $H(N)$ odd are exactly $17,31,49,71,73$. For $N=17$ the unique
diagonal witness is $x=3$, since $2\cdot 3^2=18\equiv 1 \pmod{17}$ and $4\cdot3=12<17$; and
indeed $H(17)=3$.

\begin{theorem}[The half-plane count is not separable]\label{thm:nonsep}
$\gcd(5,7)=1$ and $H(35)=6\neq 4=H(5)H(7)$, while $C(35)=32=C(5)C(7)$. Likewise
$\high(33)=4\neq 0=\high(3)\high(11)$ and $H(33)=8\neq 4=H(3)H(11)$.
\end{theorem}

\begin{proof}[Proof sketch]
Direct enumeration of the finitely many points.
\end{proof}

\section{The separable side has teeth: Blum-type semiprimes}

\begin{theorem}[Blum-type semiprimes]\label{thm:blum}
If $p\neq q$ are primes with $p\equiv q\equiv 3\pmod 4$ and $N=pq$, then
$C(N)=N+p+q+1$, hence $p+q=C(N)-N-1$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorems~\ref{thm:crt} and \ref{thm:prime} both local characters equal $-1$, so
$C(N)=(p+1)(q+1)=pq+p+q+1$.
\end{proof}

\begin{theorem}[Vieta recovery]\label{thm:vieta}
Under the hypotheses of Theorem~\ref{thm:blum}, $p$ and $q$ are the roots of
$X^2-\bigl(C(N)-N-1\bigr)X+N=0$, whose coefficients are computed from $N$ and $C(N)$ alone.
\end{theorem}

Thus the circle count of a Blum-type semiprime determines the factorisation completely; the
obstruction is purely computational, since the only known route to $C(N)$ without the
factorisation is a $\Theta(N)$ enumeration. For example $C(21)=32$ gives $p+q=10$ and
$\{p,q\}=\{3,7\}$; $C(437)=480$ gives $p+q=42$ and $\{p,q\}=\{19,23\}$.

\section{Quantitative behaviour}\label{sec:quant}

\subsection{The heuristic density}

The region $\{(x,y)\in[0,N)^2:x+y<N/2\}$ is a triangle of area $N^2/8$. If the circle points
were equidistributed we would expect $H(N)\approx C(N)/8$. Averaging $8H(N)/C(N)$ over odd
squarefree $N$ gives $1.0476$ on $[100,400)$, $1.0234$ on $[400,1000)$ and $1.0078$ on
$[1000,3000)$. The systematic positive bias is explained by the reflection identity:
$8H(N)-C(N)=\bigl(8\,\high(N)-C(N)\bigr)+8S(N)$, and $8S(N)=8\cdot2^{\omega(N)}$ is relatively
large for small $N$ only.

