"""Algorithm A: linear-time enumeration of the modular circle and all its strata."""

from __future__ import annotations

from typing import Dict, List


def circle_statistics(N: int) -> Dict[str, int]:
    """Compute C(N), H(N), high(N), S(N), R(N), D(N) in a single Theta(N) pass.

    C(N)    = #{(x,y) in [0,N)^2 : x^2 + y^2 == 1 (mod N)}
    H(N)    = #{those with 2(x+y) < N}          (the half-plane count)
    high(N) = #{those with 2(x+y) > 3N}         (the opposite corner)
    S(N)    = #{u in [0,N) : u^2 == 1 (mod N)}  (square roots of unity)
    R(N)    = #{those with 2u < N}
    D(N)    = #{x : 2x^2 == 1 (mod N), 4x < N}  (diagonal points of the cut)

    Complexity: Theta(N) time and Theta(N) space.  The inner double loop runs
    once per circle point, and C(N) <= N + O(sqrt N) for odd N, so the total
    work is linear in N.
    """
    if N < 1:
        raise ValueError("N must be positive")
    one = 1 % N

    # bucket[r] = list of y in [0,N) with y^2 == r (mod N)
    bucket: Dict[int, List[int]] = {}
    for y in range(N):
        bucket.setdefault((y * y) % N, []).append(y)

    C = H = high = D = 0
    for x in range(N):
        target = (one - x * x) % N
        for y in bucket.get(target, ()):
            C += 1
            s = 2 * (x + y)
            if s < N:
                H += 1
                if x == y:
                    D += 1
            elif s > 3 * N:
                high += 1

    S = R = 0
    for u in bucket.get(one, ()):
        S += 1
        if 2 * u < N:
            R += 1

    return {"N": N, "C": C, "H": H, "high": high, "S": S, "R": R, "D": D}


def verify_identities(N: int) -> Dict[str, bool]:
    """Check the structure theorems at a single modulus."""
    st = circle_statistics(N)
    return {
        "reflection  H = high + 2R": st["H"] == st["high"] + 2 * st["R"],
        "halving     2R = S": 2 * st["R"] == st["S"],
        "quadrant    4*high <= C": 4 * st["high"] <= st["C"],
        "parity      H = D (mod 2)": st["H"] % 2 == st["D"] % 2,
    }


if __name__ == "__main__":
    for N in (15, 33, 35, 105, 221, 437):
        st = circle_statistics(N)
        print(st, verify_identities(N))

"""Algorithm B: closed-form evaluation of the circle count from the factorisation."""

from __future__ import annotations

from typing import Dict


def factorize(n: int) -> Dict[int, int]:
    """Trial-division factorisation {prime: exponent}; O(sqrt n) worst case."""
    f: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f


def local_factor(p: int) -> int:
    """The local conic count p - chi_p(-1) at an odd prime p."""
    if p == 2:
        raise ValueError("the closed form applies to odd primes only")
    return p - 1 if p % 4 == 1 else p + 1


def circle_count_from_factorization(factorization: Dict[int, int]) -> int:
    """C(N) = prod_p p^{v_p - 1} (p - chi_p(-1)) for odd N given as {p: v_p}.

    Complexity: O(omega(N)) big-integer multiplications -- exponentially faster
    than enumeration, but it presupposes the factorisation of N.
    """
    out = 1
    for p, v in factorization.items():
        out *= p ** (v - 1) * local_factor(p)
    return out


def circle_count(N: int) -> int:
    """Convenience wrapper: factor N (odd) and apply the closed form."""
    if N % 2 == 0:
        raise ValueError("closed form stated for odd N")
    return circle_count_from_factorization(factorize(N))


if __name__ == "__main__":
    for N in (15, 21, 35, 105, 9, 25, 27, 225, 56801):
        print(f"C({N}) = {circle_count(N)}   from {factorize(N)}")

"""Algorithm C: Vieta recovery of a Blum-type semiprime from its circle count."""

from __future__ import annotations

import math
from typing import Dict, List, Tuple


def circle_count_by_enumeration(N: int) -> int:
    """C(N) by brute-force enumeration; Theta(N) time -- the only route that
    does not presuppose the factorisation."""
    bucket: Dict[int, List[int]] = {}
    for y in range(N):
        bucket.setdefault((y * y) % N, []).append(y)
    one = 1 % N
    return sum(len(bucket.get((one - x * x) % N, ())) for x in range(N))


def blum_factors_from_circle_count(N: int, C: int) -> Tuple[int, int]:
    """Recover p, q from N = pq with p == q == 3 (mod 4) and C = C(N).

    Since both local characters equal -1, C(N) = (p+1)(q+1) = N + p + q + 1,
    so s = p + q = C - N - 1 and pq = N.  Hence p and q are the two roots of
    X^2 - sX + N, recovered in O(1) arithmetic operations from N and C.
    """
    s = C - N - 1
    disc = s * s - 4 * N
    if disc < 0:
        raise ValueError("not a Blum-type semiprime circle count")
    r = math.isqrt(disc)
    if r * r != disc:
        raise ValueError("discriminant is not a perfect square")
    p, q = (s - r) // 2, (s + r) // 2
    if p * q != N:
        raise ValueError("recovery failed: inconsistent data")
    return p, q


if __name__ == "__main__":
    for N in (21, 33, 77, 209, 437, 253, 589, 989):
        C = circle_count_by_enumeration(N)
        print(f"N = {N:5d}, C(N) = {C:5d} -> factors {blum_factors_from_circle_count(N, C)}")
